"""Generate the exercise index exercises/README.md from the catalogue.

    python3 -m pn.index

Status: `todo` (no folder yet), `drafted` (net.py exists), `reviewed` (the user confirmed the
interpretation, which is marked by renaming the note's section „Interpretace“ to „Nápověda“).
"""

from pathlib import Path

from .catalog import categories, exercises

ROOT = Path(__file__).resolve().parent.parent
INDEX = ROOT / "exercises" / "README.md"

HEAD = """\
# Exercises

<!-- Generated by `make index` (python3 -m pn.index) from pn/catalog.py; do not edit by hand. -->

Every Petri net exercise from the IMS study material, grouped by category: basic models first, then single mechanisms as in the short exam questions, then marking at time t, then full word problems as at the midterm. Within a category, newer tasks come first. *Původ* says where the task comes from; the note's last section has the details.

Each note shows only the task when opened. Try the exercise first, then open the hidden sections one at a time: the hint, the net, the common mistakes, the SIMLIB model, the sources. Every note also exists as a PDF next to it.

Status: `drafted` = built and passing `make check`, the interpretation not yet confirmed (section *Interpretace*); `reviewed` = the interpretation is confirmed (section *Nápověda*); `todo` = not built yet.
"""


def status(folder):
    d = ROOT / "exercises" / folder
    if not (d / "net.py").exists():
        return "todo"
    note = d / f"{d.name}.md"
    return "reviewed" if note.exists() and "\n## Nápověda\n" in note.read_text() else "drafted"


def index():
    cats = list(categories())
    st = [status(f) for f, _, _ in exercises()]
    out = [HEAD, f"{len(st) - st.count('todo')} of {len(st)} exercises drafted, "
                 f"{st.count('reviewed')} reviewed.\n",
           "| Č. | Kategorie | Úloh | Reviewed |", "|---|---|---|---|"]
    for cat, title, exs in cats:
        n = cat.split(" - ")[0]
        rev = sum(status(f) == "reviewed" for f, _, _ in exs)
        out.append(f"| {n} | [{title}](<{cat}/>) | {len(exs)} | {rev} |")
    out.append("")
    for cat, title, exs in cats:
        out += [f"## {cat.split(' - ')[0]} {title}", "", "| Č. | Úloha | Původ | Status |", "|---|---|---|---|"]
        for f, name, origin in exs:
            s = status(f)
            cell = f"[{name}](<{f}/{f.split('/')[1]}.md>)" if s != "todo" else name
            out.append(f"| {f.split('/')[1].split(' - ')[0]} | {cell} | {origin} | {s} |")
        out.append("")
    return "\n".join(out)


def main():
    INDEX.write_text(index())


if __name__ == "__main__":
    main()
